    25  //! Information pertaining to the defined %Exiv2 value type identifiers.
    26  constexpr struct TypeInfoTable {
    27    Exiv2::TypeId typeId_;  //!< Type id
    28    const char* name_;      //!< Name of the type
    29    size_t size_;           //!< Bytes per data entry
    30    //! Comparison operator for \em typeId
    31    bool operator==(Exiv2::TypeId typeId) const {
    32      return typeId_ == typeId;
    33    }
    34    //! Comparison operator for \em name
    35    bool operator==(const std::string& name) const {
    36      return name == name_;
    37    }
    38  } typeInfoTable[] = {
