    71  const char* TypeInfo::typeName(TypeId typeId) {
    72    if (auto tit = Exiv2::find(typeInfoTable, typeId))
    73      return tit->name_;
    74    return nullptr;
    75  }
    76
    77  TypeId TypeInfo::typeId(const std::string& typeName) {
    78    if (auto tit = Exiv2::find(typeInfoTable, typeName))
    79      return tit->typeId_;
    80    return invalidTypeId;
    81  }
    82
    83  size_t TypeInfo::typeSize(TypeId typeId) {
    84    if (auto tit = Exiv2::find(typeInfoTable, typeId))
    85      return tit->size_;
    86    return 0;
    87  }
