   108  uint8_t Exiv2::DataBuf::read_uint8(size_t offset) const {
   109    if (offset >= pData_.size()) {
   110      throw std::out_of_range("Overflow in Exiv2::DataBuf::read_uint8");
   111    }
   112    return pData_[offset];
   113  }
